package com.coffeeshop.service;import com.coffeeshop.dto.CustomerCommands;import com.coffeeshop.model.CustomerModels;import com.coffeeshop.repository.CustomerRepository;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class CustomerServiceTest{private final Stub repository=new Stub();private final CustomerService service=new CustomerService(repository);@Test void normalizesAndSaves(){assertEquals(7,service.save(command(null," Ada "," Lovelace ","ada@example.com",null)));assertEquals("Ada",repository.saved.firstName());assertEquals("Lovelace",repository.saved.lastName());}@Test void validatesNameEmailAndLengths(){assertThrows(IllegalArgumentException.class,()->service.save(command(null," ",null,null,null)));assertThrows(IllegalArgumentException.class,()->service.save(command(null,"Ada",null,"invalid",null)));assertThrows(IllegalArgumentException.class,()->service.save(command(null,"x".repeat(101),null,null,null)));}@Test void updateRequiresRowVersion(){assertThrows(IllegalArgumentException.class,()->service.save(command(1L,"Ada",null,null,null)));}@Test void delegatesActivationAndFiltering(){CustomerModels.Customer c=new CustomerModels.Customer(1,"CUS1","Ada",null,null,null,null,null,null,true,new byte[]{1});service.setActive(c,false);assertFalse(repository.active);repository.rows=List.of(c);assertEquals(1,service.customers("Ada",true).size());}@Test void suppliesActiveReservationOptions(){repository.options=List.of(new CustomerModels.Option(1,"CUS1","Ada"));assertEquals(1,service.activeOptions().size());}private static CustomerCommands.Save command(Long id,String first,String last,String email,byte[]version){return new CustomerCommands.Save(id,first,last,null,null,null,email,null,true,version);}private static final class Stub implements CustomerRepository{CustomerCommands.Save saved;boolean active;List<CustomerModels.Customer>rows=List.of();List<CustomerModels.Option>options=List.of();public List<CustomerModels.Customer>find(String s,Boolean a){return rows;}public List<CustomerModels.Option>activeOptions(){return options;}public long save(CustomerCommands.Save q){saved=q;return 7;}public void setActive(long id,boolean value,byte[]v){active=value;}}
}
